using System;using System.IO;using System.IO.Compression;using System.Collections.Generic;using System.Security.Cryptography;using System.Text;using System.Xml;using System.Xml.Serialization;
namespace EanEtikety {
public sealed class UpdateFile {public string Path,Sha256;public long Size;}
[XmlRoot("LabelDesignerPackage")]public sealed class UpdatePackage {
 public int Format=1;public string Product="Pre-release",Family,SourceCommit,PackageId;public List<UpdateFile> Files=new List<UpdateFile>();
 public void Validate(){
  if(Format!=1||Product!="Pre-release"||!UpdateFiles.FamilyValid(Family)||!UpdateFiles.Hex(SourceCommit,40)||!UpdateFiles.Hex(PackageId,64)||Files==null||Files.Count<3||Files.Count>512)throw new InvalidDataException("Invalid update manifest.");
  var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;
  foreach(var f in Files){if(f==null)throw new InvalidDataException("Invalid update file.");UpdateFiles.SafeName(f.Path);if(!names.Add(f.Path)||f.Path=="package-manifest.xml"||!UpdateFiles.Hex(f.Sha256,64)||f.Size<=0||f.Size>128L*1024*1024)throw new InvalidDataException("Invalid update file.");total=checked(total+f.Size);}
  if(total>512L*1024*1024)throw new InvalidDataException("Expanded update is too large.");
  foreach(var name in names)foreach(var other in names)if(other.StartsWith(name+"/",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("File/directory collision.");
  foreach(var name in new[]{"ND-LabelDesigner.exe","ND-LabelDesigner.dll","ND-LabelDesigner.runtimeconfig.json","LabelDesigner.Core.dll","zxing.dll","coreclr.dll","hostfxr.dll","System.Private.CoreLib.dll"})if(!names.Contains(name))throw new InvalidDataException("Incomplete update package.");
  if(PackageId!=ComputeId())throw new InvalidDataException("Package identity mismatch.");
 }
 public string ComputeId(){var ordered=new List<UpdateFile>(Files);ordered.Sort((a,b)=>StringComparer.Ordinal.Compare(a.Path,b.Path));var text=new StringBuilder("1\nPre-release\n"+Family+"\n"+SourceCommit+"\n");foreach(var f in ordered)text.Append(f.Path).Append('|').Append(f.Size.ToString(System.Globalization.CultureInfo.InvariantCulture)).Append('|').Append(f.Sha256).Append('\n');return UpdateFiles.Digest(Encoding.UTF8.GetBytes(text.ToString()));}
 static bool UserDataFile(string name){string extension=Path.GetExtension(name).ToLowerInvariant();return Array.IndexOf(new[]{".xml",".csv",".xlsx",".png",".jpg",".jpeg",".svg",".pdf",".docx",".zpl",".prn",".txt",".md",".zip"},extension)>=0;}
 public static UpdatePackage Read(string file){var p=UpdateFiles.ReadXml<UpdatePackage>(file,512*1024);p.Validate();return p;}
 public void VerifyDirectory(string directory,bool allowUserData=false){Validate();UpdateFiles.NoReparse(directory);var known=new HashSet<string>(Files.ConvertAll(f=>f.Path),StringComparer.OrdinalIgnoreCase);known.Add("package-manifest.xml");var todo=new Stack<string>();todo.Push(directory);while(todo.Count>0){string dir=todo.Pop();UpdateFiles.NoReparse(dir);foreach(var file in Directory.GetFiles(dir)){UpdateFiles.NoReparse(file);string relative=file.Substring(directory.TrimEnd((char)92,(char)47).Length+1).Replace((char)92,(char)47);if(!known.Contains(relative)&&(!allowUserData||!UserDataFile(relative)))throw new InvalidDataException("Undeclared installation file: "+relative);}foreach(var child in Directory.GetDirectories(dir)){UpdateFiles.NoReparse(child);string relative=child.Substring(directory.TrimEnd((char)92,(char)47).Length+1).Replace((char)92,(char)47)+"/";if(!allowUserData&&!Files.Exists(f=>f.Path.StartsWith(relative,StringComparison.OrdinalIgnoreCase)))throw new InvalidDataException("Undeclared installation directory.");todo.Push(child);}}foreach(var f in Files){WorkContext.Check();string path=UpdateFiles.Child(directory,f.Path);UpdateFiles.NoReparseParents(directory,path);if(!File.Exists(path)||new FileInfo(path).Length!=f.Size||UpdateFiles.Hash(path)!=f.Sha256)throw new InvalidDataException("Installed file failed verification: "+f.Path);}}
}
public sealed class UpdateOffer {public string Family,SourceCommit,PackageId,AssetName,Sha256;public long Size;[XmlIgnore]public long AssetId;}
[XmlRoot("LabelDesignerUpdates")]public sealed class UpdateIndex {
 public int Format=1;public string Product="Pre-release",SourceCommit;public List<UpdateOffer> Packages=new List<UpdateOffer>();
 public void Validate(){
  if(Format!=1||Product!="Pre-release"||!UpdateFiles.Hex(SourceCommit,40)||Packages==null||Packages.Count!=1)
   throw new InvalidDataException("Invalid update index.");
  var offer=Packages[0];
  if(offer==null||!UpdateFiles.FamilyValid(offer.Family)||offer.SourceCommit!=SourceCommit||
     offer.AssetName!=UpdateFiles.AssetName(offer.Family)||!UpdateFiles.Hex(offer.PackageId,64)||
     !UpdateFiles.Hex(offer.Sha256,64)||offer.Size<=0||offer.Size>256L*1024*1024)
   throw new InvalidDataException("Invalid update offer.");
 }
}
public static class UpdateFiles {
 public const string CurrentFamily="net10-x64";
 public static bool FamilyValid(string s){return s==CurrentFamily;}
 public static string AssetName(string family){if(!FamilyValid(family))throw new ArgumentException("family");return "ND-LabelDesigner-Pre-release-Windows-NET10-x64.zip";}
 public static bool Hex(string s,int n){if(s==null||s.Length!=n)return false;foreach(char c in s)if(!(c>='0'&&c<='9')&&!(c>='a'&&c<='f'))return false;return true;}
 public static string Digest(byte[] bytes){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 public static string Hash(string path){using(var s=File.OpenRead(path))using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 public static T ReadXml<T>(string path,int limit){if(new FileInfo(path).Length>limit)throw new InvalidDataException("XML is too large.");using(var reader=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=limit})){var serializer=new XmlSerializer(typeof(T));serializer.UnknownElement+=delegate{throw new InvalidDataException("Unknown update metadata.");};return (T)serializer.Deserialize(reader);}}
 public static void SafeName(string name){if(string.IsNullOrEmpty(name)||name.Length>220||name.IndexOfAny(new[]{'\\',':','\0'})>=0||name.StartsWith("/"))throw new InvalidDataException("Unsafe update path.");foreach(string part in name.Split('/')){if(part.Length==0||part=="."||part==".."||part.EndsWith(".")||part.EndsWith(" ")||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new InvalidDataException("Unsafe update path.");string stem=part.Split('.')[0].ToUpperInvariant();if(stem=="CON"||stem=="PRN"||stem=="AUX"||stem=="NUL"||stem=="CONIN$"||stem=="CONOUT$"||stem=="CLOCK$"||stem.Length==4&&(stem.StartsWith("COM")||stem.StartsWith("LPT"))&&char.IsDigit(stem[3]))throw new InvalidDataException("Reserved update path.");}}
 public static string Child(string root,string relative){SafeName(relative);string parent=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string child=Path.GetFullPath(Path.Combine(parent,relative.Replace('/',Path.DirectorySeparatorChar)));if(!child.StartsWith(parent,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Update path escapes root.");return child;}
 public static void NoReparse(string path){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Reparse paths are not supported.");}
 public static void NoReparseParents(string root,string file){string p=Path.GetDirectoryName(file),full=Path.GetFullPath(root).TrimEnd('\\','/');while(p!=null&&p.Length>=full.Length){NoReparse(p);if(string.Equals(p,full,StringComparison.OrdinalIgnoreCase))break;p=Path.GetDirectoryName(p);}if(File.Exists(file))NoReparse(file);}
 public static void DeletePending(string root,string path){string full=Path.GetFullPath(path);string prefix=Path.GetFullPath(root).TrimEnd('\\','/')+Path.DirectorySeparatorChar;if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)||Path.GetDirectoryName(full).TrimEnd('\\','/')!=prefix.TrimEnd('\\','/')||!Path.GetFileName(full).StartsWith(".pending-",StringComparison.Ordinal))throw new InvalidOperationException("Unowned cleanup target.");if(!Directory.Exists(full))return;var todo=new Stack<string>();todo.Push(full);while(todo.Count>0){string dir=todo.Pop();NoReparse(dir);foreach(var child in Directory.GetDirectories(dir))todo.Push(child);}Directory.Delete(full,true);}
}
public static class UpdatePreparation {
 public static UpdatePackage ReadArchiveManifest(string zip){using(var z=ZipFile.OpenRead(zip)){var e=z.GetEntry("package-manifest.xml");if(e==null||e.Length>512*1024)throw new InvalidDataException("Package does not support managed updates.");using(var stream=e.Open())using(var reader=XmlReader.Create(stream,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=512*1024})){var p=(UpdatePackage)new XmlSerializer(typeof(UpdatePackage)).Deserialize(reader);p.Validate();return p;}}}
 public static string Prepare(string zip,string expectedHash,string family,string root,UpdateOffer offer=null){
  if(!UpdateFiles.FamilyValid(family)||!UpdateFiles.Hex(expectedHash,64)||new FileInfo(zip).Length>256L*1024*1024||UpdateFiles.Hash(zip)!=expectedHash)throw new InvalidDataException("Update ZIP checksum mismatch.");
  var manifest=ReadArchiveManifest(zip);if(manifest.Family!=family)throw new InvalidDataException("Wrong update platform.");if(offer!=null&&(offer.Family!=family||offer.Sha256!=expectedHash||offer.PackageId!=manifest.PackageId||offer.SourceCommit!=manifest.SourceCommit||offer.Size!=new FileInfo(zip).Length))throw new InvalidDataException("Release changed or update identity mismatch.");
  Directory.CreateDirectory(root);UpdateFiles.NoReparse(root);string temp=Path.Combine(root,".pending-"+Guid.NewGuid().ToString("N")),target=Path.Combine(root,manifest.PackageId);Directory.CreateDirectory(temp);
  try{using(var z=ZipFile.OpenRead(zip)){if(z.Entries.Count!=manifest.Files.Count+1)throw new InvalidDataException("Unexpected ZIP inventory.");var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);int index=0;foreach(var e in z.Entries){WorkContext.Report("Overujem aktualizáciu…",index++,z.Entries.Count);UpdateFiles.SafeName(e.FullName);if(!names.Add(e.FullName)||(e.ExternalAttributes&0x400)!=0||((e.ExternalAttributes>>16)&0xF000)==0xA000)throw new InvalidDataException("Duplicate or linked ZIP entry.");var file=manifest.Files.Find(f=>f.Path==e.FullName);if(e.FullName!="package-manifest.xml"&&file==null||file!=null&&file.Size!=e.Length)throw new InvalidDataException("Undeclared update file.");string path=UpdateFiles.Child(temp,e.FullName);Directory.CreateDirectory(Path.GetDirectoryName(path));UpdateFiles.NoReparseParents(temp,path);using(var input=e.Open())using(var output=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None)){var buffer=new byte[32768];long total=0;int count;while((count=input.Read(buffer,0,buffer.Length))>0){WorkContext.Check();total+=count;if(total>e.Length)throw new InvalidDataException("Expanded size mismatch.");output.Write(buffer,0,count);}if(total!=e.Length)throw new EndOfStreamException();}}}
   manifest.VerifyDirectory(temp);WorkContext.Check();if(Directory.Exists(target)){var existing=UpdatePackage.Read(Path.Combine(target,"package-manifest.xml"));if(existing.PackageId!=manifest.PackageId)throw new InvalidDataException("Existing installation identity mismatch.");existing.VerifyDirectory(target);return target;}for(int attempt=0;;attempt++){WorkContext.Check();try{Directory.Move(temp,target);return target;}catch(IOException){if(Directory.Exists(target)){var existing=UpdatePackage.Read(Path.Combine(target,"package-manifest.xml"));if(existing.PackageId!=manifest.PackageId)throw;existing.VerifyDirectory(target);return target;}if(attempt>=4)throw;}catch(UnauthorizedAccessException){if(attempt>=4)throw;}System.Threading.Thread.Sleep(50*(attempt+1));}
  }finally{if(Directory.Exists(temp))UpdateFiles.DeletePending(root,temp);}
 }
 public static string ReadChecksum(string file,string zipName){if(new FileInfo(file).Length>16384)throw new InvalidDataException("Checksum file too large.");foreach(string line in File.ReadAllLines(file)){var pieces=line.Split(new[]{' ','\t'},StringSplitOptions.RemoveEmptyEntries);if(pieces.Length==2&&pieces[1].TrimStart('*')==zipName&&UpdateFiles.Hex(pieces[0].ToLowerInvariant(),64))return pieces[0].ToLowerInvariant();}throw new InvalidDataException("ZIP not found in checksum file.");}
}
}
